@NonNull @Override public Result doWork(){
  Thread.currentThread().setPriority(THREAD_PRIORITY_BACKGROUND);
  try {
    Log.i("FTS index");
    int indexed=0;
    List<Long> ids=new ArrayList<>(INDEX_BATCH_SIZE);
    DB db=DB.getInstance(getApplicationContext());
    SQLiteDatabase sdb=FtsDbHelper.getInstance(getApplicationContext());
    SharedPreferences prefs=PreferenceManager.getDefaultSharedPreferences(getApplicationContext());
    try (Cursor cursor=db.message().getMessageFts()){
      while (cursor.moveToNext()) {
        boolean fts=prefs.getBoolean("fts",false);
        if (!fts)         break;
        long id=cursor.getLong(0);
        EntityMessage message=db.message().getMessage(id);
        if (message != null)         try {
          Log.i("FTS index=" + message.id);
          File file=message.getFile(getApplicationContext());
          String text;
          try {
            text = HtmlHelper.getFullText(file);
          } catch (IllegalCharsetNameException | UnsupportedCharsetException | NullPointerException e) {
            Log.e(e);
            continue;
          }
          try {
            sdb.beginTransaction();
            FtsDbHelper.insert(sdb,message,text);
            sdb.setTransactionSuccessful();
          }
  finally {
            sdb.endTransaction();
          }
          indexed++;
          ids.add(id);
          if (ids.size() > INDEX_BATCH_SIZE)           markIndexed(db,ids);
        }
 catch (        Throwable ex) {
          if (ex instanceof FileNotFoundException || ex instanceof OutOfMemoryError)           ids.add(id);
          Log.e(ex);
        }
      }
      markIndexed(db,ids);
    }
     Log.i("FTS indexed=" + indexed);
    return Result.success();
  }
 catch (  Throwable ex) {
    Log.e(ex);
    return Result.failure();
  }
}
